        "Ikke gi opp. Øret blir bedre for hver oppgave.": "Nie poddawaj się. Ucho staje się lepsze z każdym zadaniem.",
        "Små forskjeller er vanskelige for alle. Prøv igjen!": "Małe różnice są trudne dla każdego. Spróbuj jeszcze raz!",
        "Hør gjerne en gang til før du går videre.": "Posłuchaj jeszcze raz, zanim przejdziesz dalej.",
        "Selv pianostemmere trenger mange års trening. Du er på vei!": "Nawet stroiciele fortepianów potrzebują wielu lat ćwiczeń. Jesteś na dobrej drodze!",
        "Pust rolig, lytt godt, og prøv neste.": "Oddychaj spokojnie, słuchaj uważnie i spróbuj następnego.",
        "{n} cent": function(v){ var s = String(v.n), n = parseFloat(s.replace(',', '.')); if (/[.,]/.test(s)) return s + ' centa'; if (n === 1) return s + ' cent'; var j = n % 10, d = n % 100; return s + ((j >= 2 && j <= 4 && (d < 12 || d > 14)) ? ' centy' : ' centów'); },
